ACCOUNTS_ENC = ''

def load_accounts():
    try:
        raw = base64.b64decode(ACCOUNTS_ENC)
        _K3 = bytes.fromhex('53555045525f5345435245545f323032355f5f')
        _K4 = bytes([0x99,0x88,0x77,0x66,0x55,0x44,0x33,0x22,0x11,0x00,0xaa,0xbb,0xcc,0xdd,0xee,0xff])
        KEY2 = hashlib.sha512(_K3 + _K4).digest()[:32]
        IV2 = hashlib.sha256(_K3).digest()[:16]
        cipher2 = AES.new(KEY2, AES.MODE_CBC, IV2)
        decrypted2 = unpad(cipher2.decrypt(raw), 16)
        decompressed = base64.b64decode(decrypted2)
        _K1 = bytes.fromhex('4d415a414a495f76332e375f4b45595f32')
        _K2 = bytes([0x1a,0x2b,0x3c,0x4d,0x5e,0x6f,0x70,0x81,0x92,0xa3,0xb4,0xc5,0xd6,0xe7,0xf8,0x09])
        KEY1 = hashlib.sha256(_K1 + _K2).digest()
        IV1 = hashlib.md5(_K1).digest()[:16]
        cipher1 = AES.new(KEY1, AES.MODE_CBC, IV1)
        decrypted1 = unpad(cipher1.decrypt(decompressed), 16).decode('utf-8')
        return [x for x in decrypted1.split('\n@@@SPLIT@@@\n') if x.strip()]
    except: return []

