def parse_account(entry):
    if not entry: return None
    entry = entry.strip()
    try:
        d = json.loads(entry)
        if isinstance(d, dict):
            return (
                str(d.get('show_num_id', d.get('id', d.get('num_id', d.get('user_id', ''))))),
                str(d.get('name', d.get('username', ''))),
                str(d.get('phone', d.get('mobile', ''))),
                str(d.get('pwd', d.get('password', ''))),
                str(d.get('level', 'N/A')),
                str(d.get('gold', 'N/A')),
                str(d.get('diamond', 'N/A')),
                str(d.get('vip', 'N/A')),
                str(d.get('experience', '0')),
                str(d.get('max_exp', '0')),
            )
    except: pass
    parts = [p.strip() for p in entry.split('|')]
    if len(parts) >= 8: return tuple(parts[:8])
    parts = [p.strip() for p in entry.split('\n') if p.strip()]
    if len(parts) >= 8: return tuple(parts[:8])
    parts = [p.strip() for p in entry.split(',')]
    if len(parts) >= 8: return tuple(parts[:8])
    return None

