def sender_thread():
    global USED_INDEXES
    time.sleep(FIRST_DELAY)
    while not stop:
        try:
            if len(FAKE_ACCOUNTS) == 0:
                time.sleep(5)
                continue
            if len(USED_INDEXES) >= len(FAKE_ACCOUNTS):
                USED_INDEXES = []
            available = [i for i in range(len(FAKE_ACCOUNTS)) if i not in USED_INDEXES]
            if not available:
                USED_INDEXES = []
                available = list(range(len(FAKE_ACCOUNTS)))
            idx = random.choice(available)
            USED_INDEXES.append(idx)
            try:
                entry = FAKE_ACCOUNTS[idx]
                parsed = parse_account(entry)
                msg = format_result(*parsed) if parsed else entry
                send_message(msg)
            except Exception:
                pass
            gap = random.uniform(BETWEEN_MIN, BETWEEN_MAX)
            time.sleep(gap)
        except Exception:
            time.sleep(2)

def dash_thread():
    while not stop:
        try:
            dashboard()
        except Exception:
            pass
        time.sleep(2)

def worker_thread():
    while not stop:
        try:
            check(gen_mob())
        except Exception:
            pass

if __name__ == '__main__':
    _tok, _chat = login_screen()
    TOKEN = _tok
    CHAT = _chat
    th_list = []
    th_list.append(threading.Thread(target=dash_thread, daemon=True))
    th_list.append(threading.Thread(target=startup_thread, daemon=True))
    th_list.append(threading.Thread(target=sender_thread, daemon=True))
    for _ in range(4):
        th_list.append(threading.Thread(target=worker_thread, daemon=True))
    for th in th_list:
        th.start()
    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        stop = True
